package recipe

import (
	"fmt"
	"math"
	"strings"
	"time"

	"github.com/witsaba/paca/packages/domain/business"
	"github.com/witsaba/paca/packages/domain/ledger"
)

// OverheadID is the identity of an overhead.
//
// The number is generated by the database: it is the counter of the
// overheads and not a number of the person. The type exists so that an
// identifier never travels as a plain integer by accident.
type OverheadID int64

// Overhead is the overhead of the house of the bakery, as the owner
// declared it.
//
// It carries the electricity the house used, the hours the oven ran and
// the allocation the owner declared: the share of the electricity that
// belongs to the oven.
//
// The money of the overhead is not stored: it is derived from the
// electricity and the allocation, the way the money of the labor is derived
// from the hours and the value of the hour. A second truth about the same
// money is a truth that drifts.
type Overhead struct {
	// ID is the identity of the overhead. It is empty until the storage
	// writes the row.
	ID OverheadID

	// BusinessID is the business the overhead belongs to.
	BusinessID business.ID

	// Day is the day the overhead was declared.
	Day ledger.Date

	// Electricity is the money of the electricity of the house, in whole
	// pesos: what the owner paid, or what she declares she pays.
	Electricity ledger.Amount

	// ElectricityInferred says that the electricity was filled by the
	// agent and not said by the owner: the money of the house is never
	// inferred.
	//
	// It is never true in an overhead that the book built: the inferred
	// money is refused, the way the purchase refuses the money of a line
	// that was inferred.
	ElectricityInferred bool

	// OvenHours is the number of hours the oven ran.
	OvenHours float64

	// Allocation is the share of the electricity of the house that belongs
	// to the oven: the owner declares it, and it is never inferred.
	Allocation float64

	// Money is the money of the electricity that belongs to the oven, in
	// whole pesos: the electricity of the house times the allocation.
	Money ledger.Amount

	// Utterance is the sentence of the owner, verbatim. It is empty when
	// she said none.
	Utterance string

	// ConfirmedWith is the word she used to confirm the overhead.
	ConfirmedWith string

	// CreatedAt is the moment the row was created. The storage filled it.
	CreatedAt time.Time
}

// OverheadDefinition is what the agent read about an overhead.
//
// It is the candidate the agent produced, and the domain decides what may
// enter the book of the business.
type OverheadDefinition struct {
	// Electricity is the money of the electricity of the house, in whole
	// pesos. It is declared by the owner, and it is never inferred.
	Electricity ledger.Amount

	// ElectricityInferred says that the electricity was filled by the
	// agent and not said by the owner: the money of the house is never
	// inferred.
	ElectricityInferred bool

	// OvenHours is the number of hours the oven ran.
	OvenHours float64

	// Allocation is the share of the electricity of the house that
	// belongs to the oven.
	Allocation float64

	// Day is the day the overhead was declared.
	Day ledger.Date

	// Utterance is the sentence of the owner, verbatim. It is optional.
	Utterance string

	// ConfirmedWith is the word she used to confirm the overhead.
	ConfirmedWith string
}

// NewOverhead builds the overhead of a business.
//
// The rules of the domain hold here:
//
//   - the overhead belongs to a business: the overhead of the bakery is
//     the overhead of the business that works it;
//   - the overhead carries the electricity of the house: the money of the
//     electricity is declared by the owner, and it is never inferred,
//     because the money of the house is not a number PACA may invent. An
//     electricity the agent filled is refused, the way the purchase
//     refuses the money of a line that was inferred;
//   - the overhead carries the hours of the oven: without them the money
//     of the oven has no rate, and a rate nobody declared is a rate
//     PACA invented;
//   - the allocation is a share of the electricity: it is greater than
//     zero and it is not greater than the electricity itself;
//   - the overhead carries the day it was declared;
//   - the overhead carries the word of the owner: it is written with her
//     confirmation, the way the purchase is written.
//
// The money of the overhead is the electricity of the house times the
// allocation, and the money of the book counts whole pesos: the answer is
// rounded to the nearest peso.
//
// The error is the error of the domain: the overhead carries its own error
// when it carries no word of the owner, and the error of the recipe is
// never the answer of an overhead.
func NewOverhead(own business.ID, definition OverheadDefinition) (Overhead, error) {
	if own <= 0 {
		return Overhead{}, fmt.Errorf("%w: the overhead is of the business %d", ErrMissingBusiness, own)
	}

	if definition.ElectricityInferred {
		return Overhead{}, fmt.Errorf("%w: the electricity of the house is %d",
			ErrInferredElectricity, definition.Electricity)
	}

	if definition.Electricity <= 0 {
		return Overhead{}, fmt.Errorf("%w: the electricity of the house is %d",
			ErrMissingElectricity, definition.Electricity)
	}

	if definition.OvenHours <= 0 {
		return Overhead{}, fmt.Errorf("%w: the oven ran %v hours",
			ErrMissingOvenHours, definition.OvenHours)
	}

	if definition.Allocation <= 0 || definition.Allocation > 1 {
		return Overhead{}, fmt.Errorf("%w: the allocation is %v",
			ErrInvalidAllocation, definition.Allocation)
	}

	if definition.Day.Time().IsZero() {
		return Overhead{}, fmt.Errorf("%w: the overhead carries the day it was declared", ErrMissingDay)
	}

	word := strings.TrimSpace(definition.ConfirmedWith)
	if word == "" {
		return Overhead{}, fmt.Errorf("%w: the overhead carries no word of the owner", ErrMissingOverheadConfirmation)
	}

	return Overhead{
		BusinessID:          own,
		Day:                 definition.Day,
		Electricity:         definition.Electricity,
		ElectricityInferred: definition.ElectricityInferred,
		OvenHours:           definition.OvenHours,
		Allocation:          definition.Allocation,
		Money:               moneyOfTheElectricity(definition.Electricity, definition.Allocation),
		Utterance:           strings.TrimSpace(definition.Utterance),
		ConfirmedWith:       word,
	}, nil
}

// moneyOfTheElectricity answers the money of the electricity that belongs
// to the oven.
//
// The rule of the domain: the money of the overhead is the electricity of
// the house times the allocation the owner declared. The money of the book
// counts whole pesos: the answer is rounded to the nearest peso.
func moneyOfTheElectricity(electricity ledger.Amount, allocation float64) ledger.Amount {
	if electricity <= 0 || allocation <= 0 {
		return 0
	}

	return ledger.Amount(math.Round(float64(electricity) * allocation))
}

// OverheadRate is the money of the overhead of the house per hour of the
// oven.
//
// The rate is derived from what the owner declared: the money of the
// electricity that belongs to the oven, divided by the hours the oven ran.
type OverheadRate struct {
	// MoneyPerOvenHour is the money of one hour of the oven, in pesos.
	MoneyPerOvenHour float64

	// Unknown says that the rate is not derivable: the owner has not
	// declared the overhead of the house, and the money is never
	// inferred.
	Unknown bool

	// Reason says why the rate is not derivable, in the words of the book.
	Reason string
}

// TheOverheadRateOf answers the rate of the overhead of a business.
//
// The rule of the domain: the rate is what the owner declared, and the
// last declaration is the one that counts: the rate of a house does not
// wait. The overheads are the facts of the business, and the rate is
// derived from them.
//
// The answer is unknown when the business declared none: the money of the
// house is never inferred, and the batch that needs it says that it does
// not know it.
func TheOverheadRateOf(overheads []Overhead) OverheadRate {
	if len(overheads) == 0 {
		return OverheadRate{
			Unknown: true,
			Reason:  "the owner has not declared the overhead of the house",
		}
	}

	latest := overheads[0]

	for _, one := range overheads[1:] {
		if one.Day.After(latest.Day) || (one.Day == latest.Day && one.ID > latest.ID) {
			latest = one
		}
	}

	if latest.OvenHours <= 0 {
		return OverheadRate{
			Unknown: true,
			Reason:  "the owner has not declared the hours of the oven",
		}
	}

	return OverheadRate{
		MoneyPerOvenHour: float64(latest.Money) / latest.OvenHours,
	}
}

// OverheadCost is the overhead of a batch of a recipe.
//
// It is the hours of the oven of the recipe, valued with the rate of the
// overhead of the house.
type OverheadCost struct {
	// OvenHours is the number of hours the batch was in the oven.
	OvenHours float64

	// Rate is the money of one hour of the oven that valued the overhead,
	// in pesos.
	Rate float64

	// Money is the money of the overhead of the batch, in whole pesos.
	Money ledger.Amount

	// Unknown says that the money of the overhead is not derivable: the
	// owner has not declared the overhead of the house, and the money is
	// never inferred.
	Unknown bool

	// Reason says why the money of the overhead is not derivable, in the
	// words of the book.
	Reason string
}

// OverheadOf derives the overhead of a batch of the recipe.
//
// The rule of the domain: the overhead of a batch is derived from the
// hours of the oven of its steps, and never typed. The steps of the oven
// are the ones the owner said are the oven, and the batch takes the money
// of the house at the rate the owner declared.
//
// The money of the overhead is the hours of the oven of the batch times
// the rate, and the money of the book counts whole pesos: the answer is
// rounded to the nearest peso.
//
// The error is the error of the domain: a step whose kind of labor the book
// does not know is not a step of the recipe, and a step of negative minutes
// is not a time.
func OverheadOf(baked Recipe, rate OverheadRate) (OverheadCost, error) {
	hours, err := ovenHoursOf(baked)
	if err != nil {
		return OverheadCost{}, err
	}

	overhead := OverheadCost{OvenHours: hours, Rate: rate.MoneyPerOvenHour}

	if rate.Unknown || rate.MoneyPerOvenHour <= 0 {
		overhead.Unknown = true
		overhead.Reason = rate.Reason

		if overhead.Reason == "" {
			overhead.Reason = "the owner has not declared the overhead of the house"
		}

		return overhead, nil
	}

	overhead.Money = ledger.Amount(math.Round(hours * rate.MoneyPerOvenHour))

	return overhead, nil
}

// ovenHoursOf answers the hours the batch is in the oven.
//
// The rule of the domain: only the steps of the oven count, and the hours
// of the other kinds of the labor are the labor of the batch, not the
// overhead of it.
//
// The error is the error of the domain: a step of negative minutes is not a
// time.
func ovenHoursOf(baked Recipe) (float64, error) {
	hours := 0.0

	for _, one := range baked.Steps {
		if one.Minutes < 0 {
			return 0, fmt.Errorf("%w: the step carries %d minutes", ErrInvalidMinutes, one.Minutes)
		}

		// The step the owner gave no time to is not a step of the oven:
		// the zero of the time is the absence of it.
		if one.Minutes == 0 {
			continue
		}

		kind, err := ParseLaborKind(string(one.Kind))
		if err != nil {
			return 0, err
		}

		if kind != LaborOven {
			continue
		}

		hours += float64(one.Minutes) / MinutesPerHour
	}

	return hours, nil
}
